scripts.script:
-- Just use inf yield and noclip to step out from the match
local RunService = game:GetService("RunService");
local InfMoneyPls = game:GetService("ReplicatedStorage"):WaitForChild("RemoteFunctions"):WaitForChild("PickOption");

RunService.RenderStepped:Connect(function()
    pcall(function()
        for i = 1,4 do
            local args = {i};
            InfMoneyPls:InvokeServer(unpack(args));
        end
    end)
end)
